fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    let len = a.len();

    if len <= 1 {
        // If empty or length 1, return entire array as first part, second part empty
        (a, Vec::new())
    } else {
        // Split roughly in half (floor division)
        let mid = len / 2;
        let first = a[..mid].to_vec();
        let second = a[mid..].to_vec();
        (first, second)
    }
}